prime.script:
(function(seed){
  const c = new City(seed, 80);
  c.disastersEnabled = false;
  c.funds = 9e9;
  // 10 SOLAR arrays along the top — 1,200 MW of nameplate with ZERO smoke
  // (recomputeMaps' pollution fold adds nothing at all for OV.SOLAR).
  for (let k = 0; k < 10; k++) {
    if (c.place("solar", 4 + k * 7, 2).ok) continue;
    for (let x = 4; x <= 73; x++) if (c.place("solar", x, 2).ok) break;
  }
  for (let x = 4; x <= 75; x++) c.place("wire", x, 4);          // bus row
  const SP = [7, 26, 44, 62];                                   // wire spines
  // WATER FIRST (place() refuses an occupied tile), mains as ROWS on a 5 pitch
  // over the WHOLE map, towers seeding each segment — the gp1-baseline idiom.
  for (let y = 6; y <= 76; y += 5) {
    for (const tx of [5, 12, 35, 53, 70]) c.place("watertower", tx, y);
    for (let x = 4; x <= 75; x++) if (SP.indexOf(x) < 0) c.place("pipe", x, y);
  }
  // 12 schools + 12 hospitals — eduCov/medCov are +0.1 each in the landv fold.
  for (const sy of [13, 23, 33, 43, 53, 63]) for (const sx of [17, 47]) {
    c.place("school", sx, sy); c.place("hospital", sx + 12, sy);
  }
  // 35 wonder landmarks on a 10 x 14 lattice, every row clear of a pipe row.
  // Each is lv 120 on its own 4x4 lot and radiates LANDMARK_R 18 of civic
  // pride (landmarkCov, weight 0.6) — the widest land-value stamp in the sim.
  for (const y of [12, 22, 32, 42, 52, 62, 72]) for (const x of [8, 22, 36, 50, 64])
    c.place("pyramid", x, y);
  // one FULL park row plus a checkerboard park/zone row per road block, so
  // every zoned lot is orthogonally flanked by lv-90 parkland.
  for (let y = 9; y <= 76; y += 3) for (let x = 4; x <= 75; x++) c.place("park", x, y);
  for (let y = 10; y <= 76; y += 3) for (let x = 4; x <= 75; x++)
    if ((x + y) % 2 === 0) c.place("park", x, y);
  for (let y = 8; y <= 76; y += 3) for (let x = 4; x <= 75; x++) c.place("road", x, y);
  for (const wx of SP) for (let y = 4; y <= 76; y++) c.place("wire", wx, y);
  // the SAME three-band split the pinned baseline zones with, so both fixtures
  // carry all three demand bars (an r/c-only city deadlocks: no export base).
  for (let y = 6; y <= 76; y++) for (let x = 4; x <= 75; x++)
    c.place((y < 30) ? "zr" : (y < 52) ? "zc" : "zi", x, y);
  c.funds = 200000;
  c.powerDirty = true;
  return c;
})

